 if len(files)==4:
  meta={'id':ASSET,'version':'1.0.0','category':'scenes','assetKind':'scene','theme':'culture','style':'source-preserved-low-poly','title':TITLE,'description':'One static whole-handcraft-tool inspection-tray scene, zero new independent models. Four complete qualified originals retain every mesh buffer, normal, full PBR material and internal node hierarchy at unchanged unit metre scale: the full open-front notched postal tray with both pierced side grips, rear blank plaque and both complete runners; the whole wrapped round baren with twisted hand band; the whole empty copper canting-inspired cup and narrow bent outlet with full wooden grip; and the whole opposed-leaf tatting shuttle with its central post and thread winding. Each complete tool rests separately on a measured finite region of the original tray floor, behind its front finger recess and clear of side walls, rear plaque and one another. Only a neutral low viewing slab is scene-specific. No original geometry, colour or internal proportions changed, cropped or enlarged. This is a static collection comparison, not a shared craft workflow, postal operation, carrying arrangement or functional compatibility claim. No added paper, wax, heat, cloth, lace output, person, label, grip, load, stability, manufacture or safety capability. No rig, animation or interaction.','bounds':dict(zip(['x','y','z'],[hi[k]-lo[k]for k in range(3)]),unit='m'),'triangles':triangle_count,'materials':16,'files':files,'status':'review','license':'All rights reserved'}
  (OUT/'metadata.json').write_text(json.dumps(meta,indent=2)+'\n')
